    # 3) Try to set Color attribute to 'Yellow' (prefer combobox.select_option, fallback to fill)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Yellow")
    except Exception:
        try:
            await page.get_by_label("Color").fill("Yellow")
        except Exception:
            pass

    # 4) Open the Inventory tab to set Qty and Stock Availability
    try:
        await page.get_by_role("link", name="Inventory").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If clicking fails, inventory fields might already be visible — continue.
