            await page.get_by_role("textbox", name="Qty").fill(qty_value)
        except Exception:
            pass

    # 4b) Set Stock Availability -> In Stock (prefer combobox.select_option, fallback to checking a control)
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        try:
            # Fallback for radio/checkbox-like control labeled 'In Stock'
            await page.get_by_label("In Stock").check()
        except Exception:
            pass

    # 5) Final action: click Save (this will navigate away). Must be the last action.
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        # Fallback: click any button whose name contains 'Save'
        try:
            await page.get_by_role("button", name=lambda n: n and "Save" in n).click()
        except Exception:
            pass

    # Wait for the save/navigation to finish
    await page.wait_for_load_state("networkidle")

